const detectLocale = () => {
  const lang = navigator.language || 'en'
  if (lang === 'zh-TW' || lang === 'zh-HK') return 'zh-Hant'
  if (lang === 'zh-CN' || lang === 'zh-SG' || lang.startsWith('zh-Hans')) return 'zh-Hans'
  if (lang.startsWith('zh')) return 'zh-Hant'
  if (lang === 'pt-BR') return 'pt-BR'
  for (const code of ['ja', 'ru', 'es', 'pt', 'fr', 'de', 'it', 'ko', 'hi', 'ar', 'th']) {
    if (lang.startsWith(code)) return code
  }
  return 'en'
}

let locale = localStorage.getItem('helios-selene.locale') || detectLocale()
if (!translations[locale]) locale = 'en'

export const getLocale = () => locale
export const setLocale = (nextLocale) => {
  locale = translations[nextLocale] ? nextLocale : 'en'
  localStorage.setItem('helios-selene.locale', locale)
  document.documentElement.lang = locale
}
export const t = (key, values = {}) => {
  const value = translations[locale][key] ?? translations.en[key] ?? key
  if (Array.isArray(value)) return value
  return typeof value === 'string' ? value.replace(/\{(\w+)\}/g, (_, name) => values[name] ?? `{${name}}`) : value
}
